Method.Implementation:
Set tStatus = $$$OK
Try {
	Set tId = ..%Id()
	If ""=tId {
		Set seqKey = ""
		For {
			Set tElement = ..Record.GetNext(.seqKey)
			If (seqKey = "") Quit
			If $IsObject(tElement) && (""'=tElement.%Id()) {
				Set tElementId = tElement.%Id()
				Set tStatus = ##class(IHC.ITF.BILLING.DStruc.CBRefundToARM.OutCB.Record).%DeleteId(tElementId)
			}
			If $$$ISERR(tStatus) Quit
		}
	}
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus
